import qpack.*;import java.io.*;import java.nio.charset.StandardCharsets;class TaskBinding{static Object queue(int kind,int n){return switch(kind){case 0->new FixedQueue(n);case 1->new CircularQueue(n);default->new DynQueue(n);};}static void put(Object q,char c){((ICharQ)q).put(c);}static char get(Object q){return ((ICharQ)q).get();}static String demo(){PrintStream old=System.out;ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(PrintStream out=new PrintStream(bytes,true,StandardCharsets.UTF_8)){System.setOut(out);IQDemo.demonstrate();}finally{System.setOut(old);}return bytes.toString(StandardCharsets.UTF_8).replace("\r\n","\n");}}
